package com.bank.lp;

import java.util.*;
import java.util.logging.*;

public class LeastPrivilegeDemo {
    private static final Logger log = Logger.getLogger("LeastPriv");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        // Scoped to exactly one bucket and one ECR repo — nothing else.
        ScopedPolicy policy = new ScopedPolicy(
            Set.of("s3:GetObject", "s3:PutObject", "s3:ListBucket",
                   "ecr:BatchGetImage", "ecr:GetDownloadUrlForLayer"),
            List.of("arn:aws:s3:::nbi-customer-statements",
                    "arn:aws:s3:::nbi-customer-statements/*",
                    "arn:aws:ecr:ap-south-1:123456789012:repository/settlement-service"));

        PolicyScopeValidator v = new PolicyScopeValidator();

        log.info(() -> "Read own statement:  " + v.allowed(policy, "s3:GetObject",
                "arn:aws:s3:::nbi-customer-statements/stmt1.pdf"));
        log.info(() -> "Pull own image:      " + v.allowed(policy, "ecr:BatchGetImage",
                "arn:aws:ecr:ap-south-1:123456789012:repository/settlement-service"));
        log.warning(() -> "Read OTHER bucket:   " + v.allowed(policy, "s3:GetObject",
                "arn:aws:s3:::nbi-payroll-secret/salaries.csv"));
        log.warning(() -> "Delete (not granted):" + v.allowed(policy, "s3:DeleteObject",
                "arn:aws:s3:::nbi-customer-statements/stmt1.pdf"));
    }
}

// ─── Would be in ScopedPolicy.java ───
class ScopedPolicy {
    private final Set<String> allowedActions;
    private final List<String> allowedResources;
    ScopedPolicy(Set<String> actions, List<String> resources) {
        this.allowedActions = actions; this.allowedResources = resources;
    }
    boolean actionAllowed(String a) { return allowedActions.contains(a); }
    boolean resourceAllowed(String r) {
        return allowedResources.stream().anyMatch(res -> r.matches(res.replace("*", ".*")));
    }
}

// ─── Would be in PolicyScopeValidator.java ───
class PolicyScopeValidator {
    // Deny by default; allow only if BOTH action and resource are in scope.
    boolean allowed(ScopedPolicy p, String action, String resource) {
        return p.actionAllowed(action) && p.resourceAllowed(resource);
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), r.getMessage());
    }
}
